{"content": """"Clean end-to-end verification of the corrected Zeilberger recursion.

Translations:
  (p,q,r)  <->  [c=r, a=q-r, b=p-q]
  B_c(a)  := f(c+a, c) - (c+a)   (the unique loser b at [c,a,.], NaN if none)
  u_c = N(c) - c                  (preperiod of B_c in a-coords)
  p_c = period(c), with p_c := 1 for stale rows (their B_c terminates)

Claimed facts verified:
 F1: d(q)=f(q,r)-q equals B_r(q-r) everywhere it is defined.
 F2: for live c, B_c(a) is p_c-periodic for a >= u_c, NOT before.
 F3: Zeilberger Fundamental Recurrence L_a = mex(W_C(a) u {L_{a-1}-1,...})
     reproduces B_C(a).
 F4a: W_C(a) is q_C-periodic for a >= t_C, with t_C := max(max_{c<C} u_c, C),
      q_C := lcm{p_c : c<C}.
 F4b: periodicity does NOT (in any found case) start before max(U_C, C) by a
      margin exceeding 0 (i.e. t_C estimate is saturated-ish).
 F5: pigeonhole bound p_C <= q_C^2 (m_C+1)^{m_C},
     u_C <= max(t_C, m_C) + q_C^2 (m_C+1)^{m_C}, with m_C <= C+1.
"""
from __future__ import annotations
import sys, math
sys.path.insert(0, '.')
from GROUND_TRUTH import chomp

cen = chomp.census(0, cache="GROUND_TRUTH/cache/census_50000.tsv")
CMAX = 400
AMAX = 1400
row_cache = {}

def d_of(c, q):
    rc = cen[c]
    if rc['cls'] == 'live':
        if q >= rc['N']:
            return rc['dvals'][(q - rc['N']) % rc['period']]
    else:
        if q >= rc['deathq']:
            return None
    if c not in row_cache:
        row_cache[c] = chomp.row(c, qmax=c + AMAX)
    for (qq, ff, dd) in row_cache[c]:
        if qq == q:
            return dd
    return None

def B(c, a):
    return d_of(c, c + a)

def period_of(c):
    p = cen[c]['period']
    return p if p > 0 else 1

def u_of(c):
    return cen[c]['N'] - c

def w_of(C, a):
    out = set()
    for c in range(C):
        v2 = B(c, a + C - c)
        if v2 is not None:
            out.add(v2)
        b0 = B(c, 0)
        if b0 is not None:
            val = b0 - (C - c) - a
            if val >= 0:
                out.add(val)
    return out

def mex(s):
    m = 0
    while m in s:
        m += 1
    return m

def fund_recur(C, amax):
    L = []
    for a in range(0, amax + 1):
        S = set(w_of(C, a))
        for i in range(0, a):
            S.add(L[i] - (a - i))
        L.append(mex(S))
    return L

fail = []

# F1
for c in range(0, CMAX + 1):
    for a in range(0, AMAX + 1):
        q = c + a
        dd = d_of(c, q)
        bb = B(c, a)
        assert (dd is None) == (bb is None), (c, a, dd, bb)
print("F1 pass")

# F2
for c in range(0, CMAX + 1):
    if cen[c]['cls'] == 'stale':
        continue
    p = period_of(c)
    u = u_of(c)
    for a in range(u, AMAX - p):
        if B(c, a) != B(c, a + p):
            fail.append(f"F2 c={c} not periodic a={a}")
    if u >= 1 and B(c, u - 1) == B(c, u - 1 + p):
        fail.append(f"F2 c={c} periodic before u={u}")
print("F2 pass, fails:", len(fail))

# F3
for C in range(1, CMAX + 1):
    if cen[C]['cls'] == 'stale':
        continue
    L = fund_recur(C, AMAX)
    for a in range(0, AMAX + 1):
        if L[a] != B(C, a):
            fail.append(f"F3 C={C} a={a}: L={L[a]} B={B(C,a)}")
            break
print("F3 pass, fails:", len(fail))

# F4: t_C <= max(U_C, C), exact check of actual preperiod with period q_C
maxgap = 0
for C in range(2, CMAX + 1):
    qC = 1
    for c in range(C):
        qC = qC // math.gcd(qC, period_of(c)) * period_of(c)
    U = max(u_of(c) for c in range(C))
    t = max(U, C)
    # verify periodic for a >= t (with period q_C)
    for a in range(t, AMAX - qC):
        if w_of(C, a) != w_of(C, a + qC):
            fail.append(f"F4 C={C}: W not qC={qC}-periodic at a={a} (t={t})")
            break
    # find minimal s (actual preperiod), compare to t
    s = None
    for cand in range(0, AMAX - 2 * qC + 1):
        if all(w_of(C, a) == w_of(C, a + qC) for a in range(cand, AMAX - 2 * qC)):
            s = cand
            break
    if s is not None and s > t:
        fail.append(f"F4 C={C}: actual preperiod {s} > t={t}")
    if s is not None:
        maxgap = max(maxgap, t - s)
print("F4 pass, fails:", len(fail), "max slack t-C_actual:", maxgap)

# F5: pigeonhole inequalities with exact m_C = 1 + max_{c<C} max_a B_c(a)
worst_p = worst_u = 0.0
for C in range(2, CMAX + 1):
    qC = 1
    for c in range(C):
        qC = qC // math.gcd(qC, period_of(c)) * period_of(c)
    mC = 1 + max(B(c, a) for c in range(C) for a in range(0, AMAX + 1)
                 if B(c, a) is not None)
    if mC > C + 1:
        fail.append(f"F5 C={C}: m_C={mC} > C+1={C+1}")
    U = max(u_of(c) for c in range(C))
    tC = max(U, C)
    bound_p = qC ** 2 * (mC + 1) ** mC
    bound_u = max(tC, mC) + bound_p
    pC = period_of(C)
    uC = u_of(C)
    if pC > bound_p:
        fail.append(f"F5 C={C}: pC={pC} > {bound_p}")
    if uC > bound_u:
        fail.append(f"F5 C={C}: uC={uC} > {bound_u}")
    worst_p = max(worst_p, pC / max(bound_p, 1))
    worst_u = max(worst_u, uC / max(bound_u, 1))
print("F5 pass, fails:", len(fail), "worst ratio p/bound_p:", worst_p,
      "u/bound_u:", worst_u)

print()
if fail:
    print("FAILURES:", len(fail))
    for e in fail[:40]:
        print(" ", e)
else:
    print("ALL CHECKS PASSED (C <= %d)" % CMAX)", "path": "islands/01-recurrence/scratch/verify_recursion.py"}

